-- Atomic component 3: variant-part2-forward.sql
-- OPS: exact four preserved core/guard compositions; metadata-only forward.
-- Apply only after complete additive module and part1 legal activation forward.
-- Existing source-owned core aliases stay postgres-only; public OID/ACL/config retained.

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $part2_forward$
DECLARE spec jsonb; alias_spec jsonb; p_before pg_catalog.pg_proc%rowtype;
 p_after pg_catalog.pg_proc%rowtype; alias_before pg_catalog.pg_proc%rowtype;
