_TABLE_NAME=''inbound_email_messages'' AND TG_OP=''UPDATE'' AND NEW.company_id IS NULL\n    AND gridex_unattributed_intake.raw_hash_v1(NEW)=gridex_unattributed_intake.raw_hash_v1(OLD) THEN RETURN NEW;END IF;\n   IF TG_TABLE_NAME=''inbound_ediel_parse_results'' AND TG_OP=''UPDATE''\n    AND gridex_unattributed_intake.parse_hash_v1(NEW)=gridex_unattributed_intake.parse_hash_v1(OLD) THEN RETURN NEW;END IF;\n   RAISE EXCEPTION ''ediel_technical_intake_custody_immutable'' USING ERRCODE=''23514'';\n  END IF;\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;RETURN NEW;\nEND ","body_md5":"c81331d3c2547e3b12cccc137b9d4041"},{"signature":"gridex_unattributed_intake.immutable_v1()","body":" BEGIN\n RAISE EXCEPTION ''ediel_technical_intake_receipt_immutable'' USING ERRCODE=''23514'';END ","body_md5":"41e0af9e9739fa278954ee158306ba38"},{"signature":"gridex_ediel_technical_ack.immutable()","body":" BEGIN RAISE EXCEPTION ''ediel_technical_ack_basis_immutable'';END ","body_md5":"e589337a6d3e876d65e87075fffea3d1"},{"signature":"gridex_ediel_common_header.immutable()","body":"BEGIN RAISE EXCEPTION ''ediel_common_header_basis_immutable'';END","body_md5":"d200e73c3796c325038da595d54c4ac8"}],"dispatcher":{"signature":"public.gridex_require_outbound_reply_basis_v1(public.ediel_messages)","body_md5":"e53f0edcd41a01809569a0cc22657630","body":"\nDECLARE persisted public.ediel_messages%rowtype;\nBEGIN\n -- JWT subject/tenant read permission precede every private source read or lock.\n IF auth.role()=''authenticated'' AND (auth.uid() IS NULL OR m.company_id IS NULL OR public.gridex_actor_has_company_permission(auth.uid(),m.company_id,''communication.read'') IS NOT TRUE) THEN\n  RAISE EXCEPTION ''ediel_reply_source_scope_required'' USING ERRCODE=''42501'';\n END IF;\n IF auth.role()=''authenticated'' THEN\n  SELECT * INTO persisted FROM public.ediel_messages own WHERE own.id=m.id AND own.company_id=m.company_id;\n  IF NOT FOUND OR persisted IS DISTINCT FROM m THEN\n   RAISE EXCEPTION ''e