 spec jsonb;
 contract jsonb;
 fn pg_catalog.pg_proc%ROWTYPE;
 actual jsonb;
 before_identity jsonb;
 after_identity jsonb;
 attributes_known boolean;
 contract_known boolean;
BEGIN
 FOR spec IN SELECT value FROM jsonb_array_elements(config) LOOP
  SELECT * INTO fn FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
  IF NOT FOUND THEN RAISE EXCEPTION 'semantic_metadata_integrity_function_missing: %',spec->>'signature';END IF;
  before_identity:=to_jsonb(fn);
  SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,
   'proconfig',p.proconfig,'provolatile',p.provolatile,'prosecdef',p.prosecdef,
   'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'proparallel',p.proparallel,
   'procost',p.procost,'prorows',p.prorows,'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,
   'return_type',p.prorettype::regtype::text,'proretset',p.proretset,
   'identity_arguments',pg_get_function_identity_arguments(p.oid),
   'arguments',pg_get_function_arguments(p.oid),'language',l.lanname,
   'prokind',p.prokind,'prosupport',p.prosupport::oid::text,'provariadic',p.provariadic::text,
   'pronargs',p.pronargs,'pronargdefaults',p.pronargdefaults,'proallargtypes',p.proallargtypes,
   'proargdefaults',pg_get_expr(p.proargdefaults,0),'probin',p.probin,'prosqlbody',p.prosqlbody::text)
   INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=fn.oid;
  attributes_known:=false;
  contract_known:=false;
  FOR contract IN SELECT value FROM jsonb_array_elements(spec->'contracts') LOOP
   -- Verify the entire closed metadata variant before any accepted-body replay.
   IF actual=contract->'expected' THEN
    attributes_known:=true;
    IF md5(fn.prosrc)=contract->>'body_md5' THEN contract_known:=true;END IF;
   END IF;
  END LOOP;
  IF NOT attributes_known THEN
   RAISE EXCEPTION 'semantic_metadata_integrity_attributes_changed_requires_review: %',spec->>'signature';END IF;
  IF NOT contract_known THEN
   RAISE EXCEPTION 'semantic_metadata_integrity_body_attribute_pair_changed_requires_review: %',spec->>'signature';END IF;
  SELECT to_jsonb(p) INTO after_identity FROM pg_catalog.pg_proc p WHERE p.oid=fn.oid;
  IF after_identity IS DISTINCT FROM before_identity THEN
   RAISE EXCEPTION 'semantic_metadata_integrity_identity_changed: %',spec->>'signature';END IF;
 END LOOP;
END;
$semantic_metadata_integrity$;


DO $ops_atomic_active_signing_preserve$
BEGIN
 IF (SELECT count(*) FROM ops_api_atomic_active_signing_before)<>1
 OR (SELECT row_value FROM ops_api_atomic_active_signing_before) IS DISTINCT FROM
 (SELECT to_jsonb(p) FROM pg_catalog.pg_proc p WHERE p.oid=to_regprocedure('public.gridex_prepare_customer_contract_signature_request_v1(uuid,uuid,uuid,text,text,timestamptz,uuid,text)'))
 THEN RAISE EXCEPTION 'ops_atomic_active_signing_full_row_changed'; END IF;
END $ops_atomic_active_signing_preserve$;
DROP TABLE ops_api_atomic_active_signing_before;

COMMIT;
